// #184 M4: browser harness for the input-latency bench (see README.md in
// this directory). Not part of the shipped app — served only by
// runBench.mjs's throwaway Vite dev server. Excluded from tsconfig's
// `include`, so it is intentionally looser about typing than src/.
import { mount } from "svelte";
import AgentDetailAfter from "../src/lib/AgentDetail.svelte";
// Generated by runBench.mjs (writeBeforeSnapshot) from a pinned baseline SHA
// just before starting the dev server; not a tracked file (see .gitignore).
// eslint-disable-next-line
import AgentDetailBefore from "../src/lib/.AgentDetail.before.bench.svelte";

function state(agentId: string) {
  return {
    version: "0",
    agent_id: agentId,
    persona: { id: agentId, name: agentId, sprite_set: agentId },
    ts: "2026-07-01T00:00:00Z",
    type: "state_change",
    state: "idle",
    payload: {},
    ext: {},
  };
}

// ふじ round-2 must-fix N1: the previous "00:MM:SS" string template rolled
// over silently past seq=3599 (minute >= 60 is not a valid ISO time
// component; `new Date(...)` on it is Invalid Date). Real Date arithmetic
// has no such ceiling.
const BENCH_BASE_TS_MS = Date.parse("2026-07-01T00:00:00Z");

// Text long enough to exercise the markdown renderer per entry, mirroring a
// real assistant reply rather than a one-word stub — the #184 hypothesis is
// specifically about per-entry DOM (markdown HTML) weight.
function assistantLog(agentId: string, seq: number) {
  return {
    version: "0",
    agent_id: agentId,
    ts: new Date(BENCH_BASE_TS_MS + seq * 1000).toISOString(),
    seq,
    type: "log",
    state: "thinking",
    payload: {
      kind: "assistant",
      text:
        `## reply ${seq}\n\nこれはベンチ用の合成ログです。` +
        "段落を長めにして markdown レンダリングのコストを再現します。".repeat(3),
    },
  };
}

function buildLogs(agentId: string, count: number) {
  return Array.from({ length: count }, (_, seq) => assistantLog(agentId, seq));
}

// The composer (instruction textarea) only renders when `connection` is
// truthy (`{#if connection}` around it — you cannot instruct without one).
// Every method resolves to a no-op promise; the bench never clicks 送信,
// so nothing needs a real implementation.
function stubConnection() {
  return new Proxy(
    {},
    {
      get: (_target, prop) =>
        prop === "then" ? undefined : () => Promise.resolve(undefined),
    },
  );
}

const params = new URLSearchParams(location.search);
const count = Number(params.get("count") ?? "1000");
const variant = params.get("variant") === "before" ? "before" : "after";
const Component = variant === "before" ? AgentDetailBefore : AgentDetailAfter;

const target = document.getElementById("app");
if (!target) throw new Error("#app element not found");

mount(Component, {
  target,
  props: {
    envelope: state("agent-a"),
    logs: buildLogs("agent-a", count),
    agents: {},
    connection: stubConnection(),
    onClose: () => {},
  },
});

// Exposed for runBench.mjs (Playwright drives the page and reads these back).
declare global {
  interface Window {
    __latencies: number[];
    __armLatencyProbe: () => boolean;
  }
}

window.__latencies = [];
// Time from the textarea's `input` event (composer keystroke) to the next
// painted frame — the #184 hypothesis (layout/style recalc over the huge
// transcript DOM) shows up as a gap here, not in event-dispatch time itself.
window.__armLatencyProbe = () => {
  const textarea = document.querySelector("textarea");
  if (!textarea) return false;
  textarea.addEventListener("input", () => {
    const start = performance.now();
    requestAnimationFrame(() => {
      window.__latencies.push(performance.now() - start);
    });
  });
  return true;
};
